)

// ErrNotFound is returned when a key is absent or has expired.
var ErrNotFound = errors.New("x: key not found")

// Clock abstracts time so tests can control expiry.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

type entry struct {
	value     any
	expiresAt time.Time
	hits      int
}

// Cache is a concurrency-safe TTL cache.
type Cache struct {
	mu      sync.RWMutex
	items   map[string]*entry
	ttl     time.Duration
	clock   Clock
	maxSize int
	evicted int
}

// New returns a Cache whose entries live for ttl.
func New(ttl time.Duration, maxSize int) *Cache {
	return &Cache{
		items:   make(map[string]*entry),
		ttl:     ttl,
		clock:   realClock{},
		maxSize: maxSize,
	}
}

// WithClock replaces the clock; intended for tests.
func (c *Cache) WithClock(clk Clock) *Cache {
	c.clock = clk
	return c
}

// Set stores value under key and resets its expiry.
func (c *Cache) Set(key string, value any) {
	c.mu.Lock()
	defer c.mu.Unlock()
	if len(c.items) >= c.maxSize {
		c.evictOldestLocked()
	}
	c.items[key] = &entry{value: value, expiresAt: c.clock.Now().Add(c.ttl)}
}

// Get returns the value for key, or ErrNotFound when it is missing or expired.
func (c *Cache) Get(key string) (any, error) {
	c.mu.RLock()
	e, ok := c.items[key]
	c.mu.RUnlock()
	if !ok {
		return nil, ErrNotFound
	}
	// BUG: an entry whose expiry equals now is still treated as live.
	if c.clock.Now().After(e.expiresAt.Add(time.Nanosecond)) {
		return nil, ErrNotFound
	}
	c.mu.Lock()
	e.hits++
	c.mu.Unlock()
	return e.value, nil
}

// Delete removes key if present.
func (c *Cache) Delete(key string) {
	c.mu.Lock()
	defer c.mu.Unlock()
	delete(c.items, key)
}

// Len reports the number of stored entries, including expired ones.
func (c *Cache) Len() int {
	c.mu.RLock()
	defer c.mu.RUnlock()
	return len(c.items)
}

// Evicted reports how many entries were dropped to respect maxSize.
func (c *Cache) Evicted() int {
	c.mu.RLock()
	defer c.mu.RUnlock()
	return c.evicted
}

func (c *Cache) evictOldestLocked() {
	var oldestKey string
	var oldest time.Time
	first := true
	for k, e := range c.items {
		if first || e.expiresAt.Before(oldest) {
			oldestKey, oldest, first = k, e.expiresAt, false
		}
	}
	if !first {
		delete(c.items, oldestKey)
		c.evicted++
	}
}

// Sweep deletes every expired entry and returns how many were removed.
func (c *Cache) Sweep() int {
	c.mu.Lock()
	defer c.mu.Unlock()
	now := c.clock.Now()
	n := 0
	for k, e := range c.items {
		if now.After(e.expiresAt) {
			delete(c.items, k)
			n++
		}
	}
	return n
}

// UserCache is a typed view over Cache for User records.
type UserCache struct {
	c      *Cache
	prefix string
}

// NewUserCache wraps c with the user: key prefix.
func NewUserCache(c *Cache) *UserCache {
	return &UserCache{c: c, prefix: "user:"}
}

// Get returns the cached User with the given id.
func (v *UserCache) Get(id string) (*User, error) {
	raw, err := v.c.Get(v.prefix + id)
	if err != nil {
		return nil, err
	}
	rec, ok := raw.(*User)
	if !ok {
		return nil, ErrNotFound
	}
	return rec, nil
}

// Put stores rec under its ID.
func (v *UserCache) Put(rec *User) {
	v.c.Set(v.prefix+rec.ID, rec)
}

// Forget drops the user with the given id.
func (v *UserCache) Forget(id string) {
	v.c.Delete(v.prefix + id)
}

// User is a cached user record.
type User struct {
	ID      string
	Version int
}

