package x

import (
	"testing"
	"time"
)

type fakeClock struct{ now time.Time }

func (f *fakeClock) Now() time.Time          { return f.now }
func (f *fakeClock) Advance(d time.Duration) { f.now = f.now.Add(d) }

func TestCacheExpiry(t *testing.T) {
	clk := &fakeClock{now: time.Unix(1_700_000_000, 0)}
	c := New(time.Minute, 16).WithClock(clk)
	c.Set("k", "v1")

	t.Run("before_ttl", func(t *testing.T) {
		clk.Advance(59 * time.Second)
		if _, err := c.Get("k"); err != nil {
			t.Fatalf("Get before ttl: %v", err)
		}
	})
	t.Run("exactly_at_ttl", func(t *testing.T) {
		clk.Advance(time.Second)
		if v, err := c.Get("k"); err != ErrNotFound {
			t.Fatalf("Get at exactly ttl: got value %q, want ErrNotFound", v)
		}
	})
}

